package io.github.diodeme.ji.telemetry;

import java.util.Map;
import java.util.Objects;

/** Vendor-neutral metric observation emitted inside a diagnostic span. */
public record MetricPoint(String name, Kind kind, double value, Map<String, TelemetryValue> attributes) {
    public MetricPoint {
        if (name == null || name.isBlank()) throw new IllegalArgumentException("metric name must not be blank");
        Objects.requireNonNull(kind, "kind");
        if (!Double.isFinite(value)) throw new IllegalArgumentException("metric value must be finite");
        attributes = Map.copyOf(attributes);
    }

    public static MetricPoint counter(String name, double delta, Map<String, TelemetryValue> attributes) {
        return new MetricPoint(name, Kind.COUNTER, delta, attributes);
    }

    public static MetricPoint histogram(String name, double value, Map<String, TelemetryValue> attributes) {
        return new MetricPoint(name, Kind.HISTOGRAM, value, attributes);
    }

    public enum Kind { COUNTER, HISTOGRAM }
}
